suppressPackageStartupMessages({library(ggplot2);library(dplyr);library(tidyr);library(readr);library(patchwork);library(ggrastr)})
o<-normalizePath('8-Visualization/refinements/fig3_manuscript_revision_20261103_v4/main');tt<-file.path(o,'source_data');ff<-file.path(o,'figures');rd<-function(n)read_csv(file.path(tt,n),show_col_types=FALSE)
studycols<-read_csv('0-Data/qc/study_color_dictionary.csv',show_col_types=FALSE)
th<-theme_classic(base_family='Arial',base_size=5.5)+theme(plot.title=element_text(size=6.5,face='bold'),plot.subtitle=element_text(size=5,colour='#555555'),plot.caption=element_text(size=5,hjust=0),axis.text=element_text(size=5,colour='#333333'),axis.title=element_text(size=5.2),strip.text=element_text(size=5.2,face='bold'),strip.background=element_rect(fill='#F0F1F2',colour=NA),legend.title=element_text(size=5),legend.text=element_text(size=5),legend.position='bottom',panel.spacing=grid::unit(1.2,'mm'),plot.margin=margin(2,1,1,5))
theme_set(th)
emit<-function(p,n,w,h){saveRDS(p,file.path(ff,paste0(n,'.rds')));svglite::svglite(file.path(ff,paste0(n,'.svg')),width=w/25.4,height=h/25.4);print(p);dev.off();cairo_pdf(file.path(ff,paste0(n,'.pdf')),width=w/25.4,height=h/25.4,family='Arial');print(p);dev.off();ragg::agg_png(file.path(ff,paste0(n,'.png')),width=w,height=h,units='mm',res=600,background='white');print(p);dev.off();cat('Rendered',n,w,h,'\n')}
# B restores compact three-row-group layout using original fine compartment data.
ord<-c('Pattern_P1','Pattern_P2','WGCNA_MElightgreen','WGCNA_MEpink','Pattern_P3','WGCNA_MEblack','WGCNA_MEcyan','WGCNA_MEbrown','WGCNA_MEdarkgreen','Pattern_P4','Pattern_P5','Pattern_P6','WGCNA_MEmagenta','WGCNA_MEgreenyellow','WGCNA_MEred','WGCNA_MEdarkturquoise','WGCNA_MEtan')
pg<-setNames(c(rep('C1',4),rep('C2',5),rep('C3',8)),ord)
ll<-setNames(c('P1','P2','lightgreen | Peroxisome','pink | Catabolism','P3','black | Mitochondrial','cyan | Respiration','brown | Morphogenesis','darkgreen | Checkpoints','P4','P5','P6','magenta | Mitotic cycle','greenyellow | Hypoxia','red | Glycosylation','darkturquoise | IFN','tan | Muscle prolif.'),ord)
fine<-c('Epithelial','Hepatocyte','CD8 T','Other T','NK-like','B cell','Plasma cell','Monocytes/macrophages','Dendritic-like','Fibroblast','Pericyte-like','Endothelial')
fl<-setNames(c('Epi.','Hep.','CD8 T','Other T','NK-like','B','Plasma','Mono/Mac','DC-like','Fib.','Peri.','Endo.'),fine)
s<-rd('dotplot_summary.csv')%>%filter(Level=='Fine',Method=='UCell');b<-expand_grid(tissue=c('Adjacent','Tumor'),CellType=fine,ProgramID=ord)%>%left_join(s,by=c('tissue','CellType','ProgramID'));b$BulkGroup<-factor(pg[b$ProgramID],levels=c('C1','C2','C3'));b$ProgramID<-factor(b$ProgramID,levels=rev(ord));b$tissue<-factor(b$tissue,levels=c('Adjacent','Tumor'));b$CellType<-factor(b$CellType,levels=fine);write_csv(b,file.path(tt,'B_complete_grouped_sources.csv'))
pb<-ggplot(b,aes(CellType,ProgramID))+geom_tile(fill='#FAFAFA',colour='white',linewidth=.1)+geom_point(data=filter(b,!is.na(Score)),aes(fill=Score,size=NPatients),shape=21,stroke=.1,colour='#555555')+geom_text(data=filter(b,is.na(Score)),label='–',size=5/ggplot2::.pt,colour='#999999')+facet_grid(BulkGroup~tissue,scales='free_y',space='free_y')+scale_fill_gradientn(colours=c('#F3F3F3','#B7D7DA','#4B9CA8','#245366'),name='UCell')+scale_size_area(max_size=1.15,breaks=c(3,9,12),name='Patients')+scale_x_discrete(labels=fl)+scale_y_discrete(labels=ll)+labs(title='Program sources by bulk context',x=NULL,y=NULL)+theme(axis.line=element_blank(),axis.ticks=element_blank(),axis.text.x=element_text(angle=60,hjust=1,size=5),axis.text.y=element_text(size=5),strip.text.y=element_text(angle=270),legend.key.height=grid::unit(1.4,'mm'),legend.key.width=grid::unit(2,'mm'),legend.spacing.x=grid::unit(.5,'mm'),legend.margin=margin(0,0,0,0),legend.box.margin=margin(0,0,0,0),legend.box.spacing=grid::unit(0,'mm'),panel.spacing.y=grid::unit(1.8,'mm'),plot.margin=margin(1,1,0,4))+guides(fill=guide_colourbar(barwidth=grid::unit(13,'mm'),barheight=grid::unit(1.3,'mm'),title.position='left'),size=guide_legend(nrow=1))
emit(pb,'Figure3B_grouped_sources',78.5,61.4)
# C has one paired representative per bulk context, using full scored gene sets.
f<-rd('featureplot_selected_cells.csv.gz');prs<-c('Pattern_P1','WGCNA_MEpink','Pattern_P3','WGCNA_MEbrown','Pattern_P6','WGCNA_MEred');short<-c(Pattern_P1='P1',WGCNA_MEpink='pink',Pattern_P3='P3',WGCNA_MEbrown='brown',Pattern_P6='P6',WGCNA_MEred='red')
feature<-function(pr){dd<-f%>%mutate(Value=.data[[pr]])%>%arrange(Value);ggplot(dd,aes(UMAP1,UMAP2))+geom_point_rast(colour='#DEDEDE',size=.10,raster.dpi=600)+geom_point_rast(data=filter(dd,!is.na(Value)),aes(colour=Value),size=.10,raster.dpi=600)+scale_colour_gradientn(colours=c('#E7E7E7','#8FC4C8','#317F8C','#123E50'),limits=range(dd$Value,na.rm=TRUE),breaks=scales::pretty_breaks(n=2),name='UCell')+coord_equal(xlim=c(-10.8,22.1),ylim=c(-13.2,20),expand=FALSE)+labs(title=short[pr])+theme_void(base_family='Arial',base_size=5)+theme(plot.title=element_text(size=5.5,face='bold',hjust=.5),legend.position='right',legend.title=element_text(size=5),legend.text=element_text(size=5),legend.margin=margin(0,0,0,0),legend.box.spacing=grid::unit(0,'mm'),plot.margin=margin(0,1,0,1))+guides(colour=guide_colourbar(barwidth=grid::unit(1.2,'mm'),barheight=grid::unit(10,'mm'),title.position='top',title.hjust=.5))}
heads<-c('C1 context | P1–pink\n177 shared; 73% P1 / 66% pink','C2 context | P3–brown\n101 shared; 65% P3 / 21% brown','C3 context | P6–red\n65 shared; 71% P6 / 21% red')
pairs<-lapply(1:3,function(i){(feature(prs[2*i-1])/feature(prs[2*i]))+plot_annotation(title=heads[i],theme=theme(plot.title=element_text(size=5.6,face='bold',hjust=.5,lineheight=1.1),plot.margin=margin(0,0,0,0)))})
pc<-wrap_plots(lapply(pairs,function(p)wrap_elements(full=p)),nrow=1)+plot_annotation(title='Overlap-guided pattern–module pairs across the three bulk contexts',theme=theme(plot.title=element_text(size=6.5,face='bold'),plot.margin=margin(2,1,1,8)))
emit(pc,'Figure3C_three_pairs',174,53)
# D uses the same six sets and original patient-level statistics.
d<-rd('D_patient_pairs.csv');st<-rd('D_existing_statistics.csv');cohorts<-c('GSE151530','GSE138709');shapes<-c(GSE151530=16,GSE138709=17);plots<-list();plotted<-list()
for(j in 1:6){q<-filter(d,PanelOrder==j);ss<-filter(st,PanelOrder==j);pr<-unique(q$ProgramID);other<-unique(q$Other);ti<-unique(q$tissue);v<-bind_rows(transmute(q,PanelOrder,ProgramID,PatientKey,patient,cohort,tissue,Compartment='Epithelial',X=1,Score=EpithelialScore),transmute(q,PanelOrder,ProgramID,PatientKey,patient,cohort,tissue,Compartment=Other,X=2,Score=OtherScore));v$cohort<-factor(v$cohort,levels=cohorts);plotted[[j]]<-v
 qt<-vapply(cohorts,function(co){r<-ss[ss$cohort==co,];if(nrow(r)==0)return('');if(is.na(r$FDR))sprintf('%s: n=%d; q=NE',sub('GSE','',co),r$NPatients)else sprintf('%s: n=%d; q=%.3f',sub('GSE','',co),r$NPatients,r$FDR)},character(1));qt<-paste(qt[nzchar(qt)],collapse='\n')
 plots[[j]]<-ggplot(v,aes(X,Score,group=PatientKey))+geom_line(colour='#9DA8AC',linewidth=.25)+geom_point(aes(shape=cohort),colour='#304F5C',size=1.35,stroke=.25,show.legend=(j==3))+scale_shape_manual(values=shapes,limits=cohorts,drop=FALSE,name=NULL)+scale_x_continuous(breaks=c(1,2),labels=c('Epi.',if(other=='Hepatocyte')'Hep.'else'Mye.'),limits=c(.75,2.25),expand=c(0,0))+scale_y_continuous(limits=c(0,max(v$Score)*1.1),breaks=scales::pretty_breaks(n=3),expand=expansion(mult=c(0,.02)))+labs(title=short[pr],subtitle=paste0(ti,'; n=',n_distinct(v$PatientKey)),caption=qt,x=NULL,y=if(j==1)'UCell score'else NULL)+theme(plot.title=element_text(size=5.7,face='bold',hjust=.5),plot.subtitle=element_text(size=5,hjust=.5),plot.caption=element_text(size=5,hjust=0,lineheight=1.05),legend.key.size=grid::unit(2,'mm'),legend.margin=margin(0,0,0,0),plot.margin=margin(1,2,1,1))}
write_csv(bind_rows(plotted),file.path(tt,'D_plotted_points.csv'))
pd<-wrap_plots(plots,nrow=1,guides='collect')+plot_annotation(title='Patient support for the same six representative programs',subtitle='C1-context pair: adjacent epithelial–hepatocyte. C2/C3-context pairs: tumor epithelial–myeloid.',caption='Each line joins one patient within tissue. Cohort shapes; q: original full-family BH. Epi., epithelium; Hep., hepatocyte; Mye., myeloid.',theme=theme(plot.title=element_text(size=6.5,face='bold'),plot.subtitle=element_text(size=5),plot.caption=element_text(size=5,hjust=0),plot.margin=margin(2,1,1,8)))&theme(legend.position='bottom')
emit(pd,'Figure3D_six_patient_pairs',174,58)
# E is tumor only; adjacent context is not mixed into its patient columns.
e<-rd('E_patient_compartment_grid.csv');pats<-e%>%distinct(PatientKey,patient,PatientOrder)%>%arrange(PatientOrder);e$PatientKey<-factor(e$PatientKey,levels=pats$PatientKey);e$ProgramID<-factor(e$ProgramID,levels=rev(prs));e$CellType<-factor(e$CellType,levels=c('Epithelial','Myeloid','T_NK'));e$cohort<-factor(e$cohort,levels=cohorts)
pe<-ggplot(e,aes(PatientKey,ProgramID))+geom_tile(aes(fill=Score),colour='white',linewidth=.13)+geom_text(data=filter(e,is.na(Score)),label='–',size=5/ggplot2::.pt,colour='#999999')+facet_grid(CellType~cohort,scales='free_x',space='free_x',labeller=labeller(CellType=c(Epithelial='Epithelium',Myeloid='Myeloid',T_NK='T / NK')))+scale_fill_gradientn(colours=c('#F4F4F4','#B7D7DA','#4B9CA8','#245366'),limits=c(0,max(e$Score,na.rm=TRUE)),name='UCell',na.value='#E4E4E4')+scale_y_discrete(labels=short)+scale_x_discrete(labels=setNames(pats$patient,pats$PatientKey),drop=TRUE)+labs(title='Tumor-only distributions of the same six programs across compartments',subtitle=sprintf('16 patients; %d/%d estimable. Clean eligibility; equal-library patient means. Grey/dash: unsupported.',sum(!is.na(e$Score)),nrow(e)),x=NULL,y=NULL)+theme(axis.line=element_blank(),axis.ticks=element_blank(),axis.text.x=element_text(angle=45,hjust=1),legend.position='right',legend.key.height=grid::unit(3,'mm'),legend.key.width=grid::unit(2,'mm'),strip.text.y=element_text(angle=0),plot.margin=margin(2,1,1,8),panel.spacing.y=grid::unit(1.3,'mm'))
emit(pe,'Figure3E_tumor_compartments',174,63)
